-- Mats Forever
-- Shows on a crafting material's tooltip which professions use it and in how many recipes, from the
-- game's own data, so it covers professions the character doesn't have. Holding Shift lists the recipes.
--
-- Files, in load order (see the .toc):
--   Core.lua          namespace, saved settings, the character's professions, slash command
--   Data\Forever.lua  the recipe data, generated by tools\gen-reagents.js
--   Tooltip.lua       the tooltip lines
--   Options.lua       the options page

local ADDON_NAME, ns = ...

ns.ADDON_NAME = ADDON_NAME

-- Whether a value the game handed us can be read. In combat the game can hide some values from addons.
function ns.Readable(value)
	return not (issecretvalue and issecretvalue(value))
end

---------------------------------------------------------------------------
-- Saved settings
---------------------------------------------------------------------------

ns.DEFAULTS = {
	tooltip = true,    -- add the line to material tooltips
	recipeList = true, -- holding Shift lists the recipes
	onlyMine = false,  -- leave out professions the character doesn't have
}

---------------------------------------------------------------------------
-- Profession names and the character's own professions
---------------------------------------------------------------------------

-- A profession's name in the game's language, falling back to English.
function ns.ProfessionName(id)
	local names = ns.PROFESSION_NAMES[GetLocale()]
	return names and names[id] or ns.PROFESSIONS[id]
end

-- profession ID -> the character's skill in it, for the character's professions. Built when first
-- needed, and again whenever the character's skills change.
local mine

local function readMyProfessions()
	mine = {}
	local byName = {}
	for id in pairs(ns.PROFESSIONS) do byName[ns.ProfessionName(id)] = id end

	if GetProfessions and GetProfessionInfo then
		for _, index in pairs({ GetProfessions() }) do
			local name, _, rank, _, _, _, skillLine = GetProfessionInfo(index)
			local id = (skillLine and ns.PROFESSIONS[skillLine] and skillLine) or byName[name]
			if id then mine[id] = tonumber(rank) or 0 end
		end
	end
	if GetNumSkillLines and GetSkillLineInfo then
		for i = 1, GetNumSkillLines() do
			local name, isHeader, _, rank = GetSkillLineInfo(i)
			if name and not isHeader and byName[name] then mine[byName[name]] = tonumber(rank) or 0 end
		end
	end
end

local function myProfessions()
	if not mine then readMyProfessions() end
	local list = mine
	-- Right after login the game may not have told us the character's skills yet; ask again next time
	-- rather than keep an empty list.
	if next(mine) == nil then mine = nil end
	return list
end

function ns.IsMyProfession(id)
	return myProfessions()[id] ~= nil
end

-- The character's skill in a profession, or nil when the character doesn't have it.
function ns.MySkill(id)
	return myProfessions()[id]
end

---------------------------------------------------------------------------
-- Loading
---------------------------------------------------------------------------

local events = CreateFrame("Frame")
events:RegisterEvent("ADDON_LOADED")
events:RegisterEvent("SKILL_LINES_CHANGED")
events:SetScript("OnEvent", function(self, event, name)
	if event == "SKILL_LINES_CHANGED" then
		mine = nil
	elseif name == ADDON_NAME then
		self:UnregisterEvent("ADDON_LOADED")
		MatsForeverDB = MatsForeverDB or {}
		for key, value in pairs(ns.DEFAULTS) do
			if MatsForeverDB[key] == nil then MatsForeverDB[key] = value end
		end
		ns.db = MatsForeverDB
		ns.CreateOptions()
	end
end)

---------------------------------------------------------------------------
-- Slash command
---------------------------------------------------------------------------

SLASH_MATSFOREVER1 = "/matsforever"
SlashCmdList.MATSFOREVER = function()
	ns.OpenOptions()
end
